import { tags } from "typia";

/**
 * Attachment associated with a discussion board article.
 *
 * Attachments include a unique id, reference to their parent article, filename,
 * type, URL/path, and timestamps.
 *
 * Supports both images and general files linked securely to their article.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IDiscussionBoardArticleAttachment = {
  /** Unique identifier of the attachment. */
  id: string & tags.Format<"uuid">;

  /** Foreign key to the parent discussion board article. */
  discussion_board_article_id: string & tags.Format<"uuid">;

  /** Original filename of the attachment. */
  filename: string;

  /** MIME type or file type such as image, pdf, etc. */
  file_type: string;

  /** URL or storage path of the attachment file. */
  file_url: string;

  /** Timestamp when the attachment was created. */
  created_at: string & tags.Format<"date-time">;

  /** Timestamp when the attachment was last updated. */
  updated_at: string & tags.Format<"date-time">;

  /** Soft delete timestamp, null if active. */
  deleted_at?: (string & tags.Format<"date-time">) | null | undefined;
};
